"""Literal capabilities full table: shared-column and overflow diagnostics before implementation."""
from pathlib import Path
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const initial=','let state=','const esc=','const icons=','const icon=','const t=','const btn=','const pill=','const notice=','const heading=','const categoryDefs=','function capabilities(')))
script=defs+'''
for(const language of ['ko','en'])for(const width of [478,610,656,858,904,1118]){lang=language;const f=document.createElement('div');f.className='fixture';f.style.width=(width+2)+'px';f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());f.dataset.id=language+'-'+width;document.getElementById('fixtures').append(f)}
for(const language of ['ko','en'])for(const mode of ['min-content','max-content']){lang=language;const f=document.createElement('div');f.className='intrinsic';f.innerHTML=capabilities();f.querySelectorAll('.page-heading,.notice,.section').forEach(x=>x.remove());f.dataset.id=language+'-'+mode;f.querySelector('table').style.width=mode;document.getElementById('intrinsics').append(f)}
function measure(f){const shell=f.querySelector('.table-shell'),table=f.querySelector('table'),r=shell.getBoundingClientRect(),box=e=>{const q=e.getBoundingClientRect();return{x:q.x-r.x,y:q.y-r.y,width:q.width,height:q.height}},s=getComputedStyle(shell);return{id:f.dataset.id,shell:box(shell),table:box(table),headers:[...table.querySelectorAll('thead th')].map(box),rows:[...table.querySelectorAll('tbody tr')].map(e=>({box:box(e),cells:[...e.cells].map(box)})),clientWidth:shell.clientWidth,clientHeight:shell.clientHeight,scrollWidth:shell.scrollWidth,scrollHeight:shell.scrollHeight,scrollLeft:shell.scrollLeft,overflowX:s.overflowX,overflowY:s.overflowY,border:s.border,borderRadius:s.borderRadius,background:s.backgroundColor,columns:[...table.querySelector('thead tr').cells].map(e=>e.getBoundingClientRect().width)}}
document.getElementById('capabilitytable-record').onclick=async()=>{await document.fonts.ready;const res=await fetch('/evidence/preflight-capabilitytable-'+(new URLSearchParams(location.search).get('os')==='mac'?'mac':'windows')+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,tables:[...document.querySelectorAll('.fixture')].map(measure),intrinsics:[...document.querySelectorAll('.intrinsic')].map(measure)})});if(!res.ok)throw Error('Record failed');document.getElementById('capabilitytable-record').textContent='Capability table diagnostics recorded'};
'''
(o/'capabilitytable-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
(o/'capabilitytable.html').write_text('<!doctype html><meta charset="utf-8"><title>CapabilityTable · original isolation</title><link rel="stylesheet" href="capabilitytable-original.css"><style>.fixture{position:absolute;left:30px;top:40px}.fixture:not(:first-child),.intrinsic{visibility:hidden}.intrinsic{position:absolute;left:30px;top:40px;width:1200px}.fixture *,.intrinsic *{animation:none!important;transition:none!important}</style><div id="fixtures"></div><div id="intrinsics"></div><button id="capabilitytable-record" style="position:fixed;right:20px;top:20px">Record CapabilityTable</button><script>'+script+'</script>')
print('Literal full-table12 and min/max diagnostics4 prepared; product code absent')
